{"command": "cd $WORKSPACE_DIR && python3 - <<'PY'
import docx, re
for path in ['output/loan-agreement-draft.docx','output/cover-memorandum.docx']:
    d = docx.Document(path)
    txt = "\n".join(p.text for p in d.paragraphs)
    for t in d.tables:
        for r in t.rows:
            for c in r.cells:
                txt += "\n" + c.text
    print("=====", path, "words:", len(txt.split()))
    for bad in ['TODO','XXX','TBD]','None','nan','[●]','  |  ','llm','as an AI']:
        if bad in txt: print("  FLAG:", bad, txt.count(bad))
    # check issue numbering in memo
    if 'cover' in path:
        found = sorted({int(m.group(1)) for m in re.finditer(r'Issue (\d{1,2}) \u2014', txt)})
        print("  issues defined:", found)
        refs = sorted({int(x) for m in re.finditer(r'\(Issue[s]? ([0-9, and]+)\)', txt) for x in re.findall(r'\d+', m.group(1))})
        print("  issues referenced:", refs)
PY"}

